<section class="surface-card request-evidence-section" id="request-evidence" aria-labelledby="evidence-title"><div class="card-heading"><div><p class="eyebrow">WORK DOCUMENTATION</p><h2 id="evidence-title">Before and after</h2></div><span class="mini-pill">Round <?= $requestRound ?></span></div><p class="admin-form-intro">Compare photos from the same work round. Upload times are recorded, but photos alone cannot prove when or where work happened.</p>
<?php if (!$requestEvidence): ?><div class="admin-empty"><?= icon('camera', 'size-8') ?><h3>No evidence photos yet</h3><p><?= $careRequest['status'] === 'in_progress' ? 'The caretaker must add before and after photos before submitting work.' : 'This request has no photo evidence. If it was submitted before Phase 6, review its work note in the timeline.' ?></p></div><?php endif; ?>
<?php foreach ($evidenceByRound as $roundNumber => $stages): ?><div class="evidence-round"><h3>Work round <?= (int) $roundNumber ?><?= (int) $roundNumber === $requestRound ? ' · Current' : ' · Earlier' ?></h3><div class="evidence-compare"><?php foreach (['before', 'after'] as $stage): ?><div class="evidence-stage"><div class="evidence-stage-heading"><span class="evidence-stage-icon"><?= icon($stage === 'before' ? 'clock' : 'check', 'size-4') ?></span><h4><?= ucfirst($stage) ?></h4><small><?= count($stages[$stage] ?? []) ?> photo<?= count($stages[$stage] ?? []) === 1 ? '' : 's' ?></small></div><?php if (empty($stages[$stage])): ?><p class="evidence-empty">No <?= $stage ?> photo for this round.</p><?php else: ?><div class="evidence-photo-list"><?php foreach ($stages[$stage] as $item): ?><figure class="evidence-photo"><img src="?page=request-evidence&amp;id=<?= (int) $item['id'] ?>" alt="<?= e(ucfirst($stage) . ' evidence' . ($item['caption'] ? ': ' . $item['caption'] : '')) ?>" loading="lazy"><figcaption><strong><?= e($item['caption'] ?: ucfirst($stage) . ' photo') ?></strong><small>Uploaded <?= e(date('M j, Y · g:i A', strtotime($item['uploaded_at']))) ?> by <?= e($item['uploader_name']) ?></small><?php if ($role === 'caretaker' && $careRequest['status'] === 'in_progress' && (int) $roundNumber === $requestRound && (int) $item['id'] > 0): ?><form method="post" action="<?= $requestAction ?>" data-confirm-remove="Remove this evidence photo?"><?= csrf_field() ?><input type="hidden" name="action" value="remove_request_evidence"><input type="hidden" name="request_id" value="<?= $requestId ?>"><input type="hidden" name="evidence_id" value="<?= (int) $item['id'] ?>"><button type="submit">Remove photo</button></form><?php endif; ?></figcaption></figure><?php endforeach; ?></div><?php endif; ?></div><?php endforeach; ?></div></div><?php endforeach; ?>
<?php if ($role === 'caretaker' && $careRequest['status'] === 'in_progress'): ?><div class="evidence-upload-grid"><?php foreach (['before', 'after'] as $stage): ?><?php $canAdd = $currentEvidenceCounts[$stage] < REQUEST_EVIDENCE_PER_STAGE && ($stage === 'before' ? $currentEvidenceCounts['after'] === 0 : $currentEvidenceCounts['before'] > 0); ?><form method="post" action="<?= $requestAction ?>" enctype="multipart/form-data" class="evidence-upload-form"><?= csrf_field() ?><input type="hidden" name="action" value="upload_request_evidence"><input type="hidden" name="request_id" value="<?= $requestId ?>"><input type="hidden" name="stage" value="<?= $stage ?>"><h3>Add a <?= $stage ?> photo</h3><p><?= $stage === 'before' ? 'Photograph the grave before the care work begins.' : 'Photograph the result after the care work is done.' ?></p><div class="form-field"><label for="evidence-<?= $stage ?>-file"><?= ucfirst($stage) ?> photo</label><input class="file-input file-input-bordered w-full" id="evidence-<?= $stage ?>-file" name="photo" type="file" accept="image/jpeg,image/png,image/webp" required <?= $canAdd ? '' : 'disabled' ?>><small>JPEG, PNG, or WebP · up to 5 MB · up to 16 megapixels</small></div><div class="form-field"><label for="evidence-<?= $stage ?>-caption">Caption <span class="optional-label">Optional</span></label><input class="input input-bordered w-full" id="evidence-<?= $stage ?>-caption" name="caption" maxlength="200" placeholder="Describe what this photo shows" <?= $canAdd ? '' : 'disabled' ?>></div><button class="btn btn-outline btn-primary btn-sm" type="submit" <?= $canAdd ? '' : 'disabled' ?>>Upload <?= $stage ?> photo</button><?php if (!$canAdd && $stage === 'after' && $currentEvidenceCounts['before'] === 0): ?><small>Add a before photo first.</small><?php endif; ?></form><?php endforeach; ?></div><?php endif; ?>
</section>
